#include <bits/stdc++.h>
using namespace std;

#define rep(i, a, b) for(int i = (a); i < (b); ++i)
#define repr(i, a, b) for(int i = (a)-1; i >= (b); --i)
#define all(x) (x).begin(), (x).end()
#define sz(x) (int)(x).size()
#define pb push_back
#define mp make_pair
#define fi first
#define se second
typedef long long ll;
typedef pair<int, int> pii;
typedef vector<int> vi;

const int MOD = 1000000007;
const int INF = 1e9;

inline ll gcd(ll a, ll b) { return b ? gcd(b, a % b) : a; }
inline ll lcm(ll a, ll b) { return a / gcd(a, b) * b; }

ll modpow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

inline int modadd(int a, int b, int mod = MOD) {
    a += b;
    if (a >= mod) a -= mod;
    return a;
}

inline int modsub(int a, int b, int mod = MOD) {
    a -= b;
    if (a < 0) a += mod;
    return a;
}

inline int modmul(int a, int b, int mod = MOD) {
    return (int)((ll)a * b % mod);
}

inline int modinv(int a, int mod = MOD) {
    return modpow(a, mod - 2, mod);
}

void fwht(int *a, int n, bool invert) {
    for (int len = 1; len < n; len <<= 1) {
        for (int i = 0; i < n; i += len << 1) {
            for (int j = 0; j < len; ++j) {
                int x = a[i + j], y = a[i + j + len];
                if (!invert) {
                    a[i + j] = modadd(x, y);
                    a[i + j + len] = x;
                } else {
                    a[i + j] = modadd(x, modsub(y));
                    a[i + j + len] = y;
                }
            }
        }
    }
}

vector<int> subset_convolution(vector<int> a, int k, int mod) {
    int n = a.size();
    int N = 1;
    while (N < n) N <<= 1;
    a.resize(N);

    const int LOG = 19;
    vector<vector<int>> f(LOG, vector<int>(N, 0));

    for (int i = 0; i < LOG; ++i) {
        for (int j = 0; j < N; ++j) {
            if (__builtin_popcount(j) == i) {
                f[i][j] = (j < (int)a.size()) ? a[j] : 0;
            }
        }
        fwht(f[i].data(), N, false);
    }

    vector<vector<int>> g(LOG, vector<int>(N, 0));

    for (int i = 0; i < N; ++i) {
        vector<int> vals(LOG);
        for (int j = 0; j < LOG; ++j) {
            vals[j] = f[j][i];
        }

        vector<int> res(LOG, 0);
        res[0] = 1;
        for (int _ = 0; _ < k; ++_) {
            vector<int> tmp(LOG, 0);
            for (int j = 0; j < LOG; ++j) {
                for (int l = 0; l + j < LOG; ++l) {
                    tmp[j + l] = modadd(tmp[j + l], modmul(res[j], vals[l], mod), mod);
                }
            }
            res = tmp;
        }

        for (int j = 0; j < LOG; ++j) {
            g[j][i] = res[j];
        }
    }

    vector<int> result(N, 0);
    for (int i = 0; i < LOG; ++i) {
        vector<int> temp = g[i];
        fwht(temp.data(), N, true);
        for (int j = 0; j < N; ++j) {
            if (__builtin_popcount(j) == i) {
                result[j] = temp[j];
            }
        }
    }

    result.resize(n);
    return result;
}

const int MAXN = 1000005;
int n, k, p;
int fact[MAXN], invfact[MAXN];
int f_arr[MAXN];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> p;

    int nn = n;
    for (int i = 0; i <= n; ++i) {
        if ((n & i) == i) {
            int t = 0;
            for (int j = 0; j < 20; ++j) {
                if (n & (1 << j)) {
                    t <<= 1;
                    t |= (i >> j & 1);
                }
            }
            f_arr[t] = i;
            nn = t;
        }
    }

    if (n & 1) {
        cout << modpow(k, n, p) << '\n';
        return 0;
    }

    fact[0] = 1;
    for (int i = 1; i < MAXN; ++i) {
        fact[i] = modmul(fact[i-1], i, p);
    }
    for (int i = 0; i < MAXN; ++i) {
        invfact[i] = modinv(fact[i], p);
    }

    vector<int> a(nn + 1);
    for (int i = 0; i <= nn; ++i) {
        a[i] = invfact[f_arr[i]];
    }

    int res = modpow(k, n, p);
    a = subset_convolution(a, k, p);
    res = modsub(res, modmul(a[nn], fact[n], p), p);
    cout << res << '\n';

    return 0;
}
